size_t pqcp_runtime_resource_scenario_catalog_count(void)
{
	return ARRAY_SIZE(runtime_resource_scenarios);
}

int pqcp_runtime_resource_scenario_catalog_get(
	size_t index,
	struct pqcp_operation_scenario_case *test_case)
{
	if (index >= ARRAY_SIZE(runtime_resource_scenarios) ||
	    test_case == NULL) {
		return -EINVAL;
	}
	*test_case = runtime_resource_scenarios[index];
	test_case->schema_version =
		PQCP_OPERATION_SCENARIO_SCHEMA_VERSION;
	test_case->domain = PQCP_OPERATION_SCENARIO_RUNTIME_RESOURCE;
	test_case->case_id =
		PQCP_OPERATION_SCENARIO_CASE_ID(
			test_case->domain,
			test_case->initial_condition,
			test_case->first_operation,
			test_case->second_operation);
	return 0;
}

int pqcp_runtime_resource_scenario_catalog_audit(void)
{
	if (ARRAY_SIZE(runtime_resource_scenarios) !=
	    PQCP_OPERATION_SCENARIO_CASES_PER_DOMAIN) {
		return -EBADMSG;
	}
	for (size_t index = 0U;
	     index < ARRAY_SIZE(runtime_resource_scenarios);
	     ++index) {
		struct pqcp_operation_scenario_case test_case;
		int ret;

		ret = pqcp_runtime_resource_scenario_catalog_get(
			index, &test_case);
		if (ret != 0) {
			return ret;
		}
		ret = pqcp_operation_scenario_verify(
			&test_case);
		if (ret != 0) {
			return ret;
		}
	}
	return 0;
}
